"""Custom migration operations.

`EnableRLS` applies `apps.core.db.enable_rls()` SQL on PostgreSQL and is a
no-op on SQLite (unit tests), so one migration works on both backends while
`logistimus.E001` still fails CI when a tenant table lacks its policy.
"""

from __future__ import annotations

from django.db import migrations


class EnableRLS(migrations.RunSQL):
    """Run the RLS DDL only where RLS exists (PostgreSQL)."""

    def __init__(self, sql: str, policy_name: str, *, user_column: str | None = None):
        # `sql` is the table name; the real statement is generated by
        # apps.core.db.enable_rls so the NULLIF guard lives in one place.
        from apps.core.db import enable_rls

        self.table_name = sql
        self.policy_name = policy_name
        self.user_column = user_column
        super().__init__(
            enable_rls(sql, policy_name, user_column=user_column),
            reverse_sql=migrations.RunSQL.noop,
        )

    def database_forwards(self, app_label, schema_editor, from_state, to_state):
        if schema_editor.connection.vendor != "postgresql":
            return
        super().database_forwards(app_label, schema_editor, from_state, to_state)

    def database_backwards(self, app_label, schema_editor, from_state, to_state):
        if schema_editor.connection.vendor != "postgresql":
            return
        super().database_backwards(app_label, schema_editor, from_state, to_state)
